<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { apiRequest } from './api'
type App = { id: string; name: string; version: string; description: string; category: string; status: string }
type Plugin = { id: string; name: string; version: string; description: string; plugin_type: string }
type OfficialPlugin = { id: string; plugin_id: string; name: string; description: string; version: string; author: string; kind: string; size: string; install_url: string; installed: boolean; installed_version?: string; upgrade_available: boolean }
type MarketPlugin = { id: string; display_name: string; developer: string; owner: string; version: string; downloads: number; view_count: number; details_url: string | null; locales: Record<string, { description?: string; category?: string }>; is_featured: boolean }
type SyncConfig = { key: string; url: string; last_synced_at: string | null; synced_count: number; status: string }
const activeTab = ref<'installed' | 'official' | 'market'>('installed')
const apps = ref<App[]>([]), plugins = ref<Plugin[]>([]), official = ref<OfficialPlugin[]>([]), market = ref<MarketPlugin[]>([])
const configs = ref<SyncConfig[]>([]), error = ref(''), notice = ref(''), source = ref(''), marketSearch = ref(''), marketCategory = ref('')
const loading = ref(false), officialLoading = ref(false), marketLoading = ref(false), installing = ref(false), syncing = ref(''), syncOpen = ref(false)
async function refreshInstalled() { loading.value = true; try { const [pawapps, installed] = await Promise.all([apiRequest<{ apps: App[] }>('/pawapps'), apiRequest<Plugin[]>('/plugins')]); apps.value = pawapps.apps; plugins.value = installed; error.value = '' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not load installed plugins.' } finally { loading.value = false } }
async function refreshOfficial() { officialLoading.value = true; try { official.value = (await apiRequest<{ plugins: OfficialPlugin[] }>('/plugins/catalog')).plugins; error.value = '' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not load the official catalog.' } finally { officialLoading.value = false } }
async function refreshMarket() { marketLoading.value = true; try { const query = new URLSearchParams({ page_number: '1', page_size: '100', sort_by: 'downloads' }); if (marketSearch.value.trim()) query.set('search', marketSearch.value.trim()); if (marketCategory.value) query.set('category', marketCategory.value); market.value = (await apiRequest<{ data: { plugins: MarketPlugin[] } }>(`/plugins/market/search?${query}`)).data.plugins; error.value = '' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not load the plugin market.' } finally { marketLoading.value = false } }
async function refreshConfigs() { try { configs.value = await apiRequest<SyncConfig[]>('/plugins/sync-config') } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not load synchronization settings.' } }
async function selectTab(tab: 'installed' | 'official' | 'market') { activeTab.value = tab; if (tab === 'official' && !official.value.length) await refreshOfficial(); if (tab === 'market' && !market.value.length) await refreshMarket() }
async function sync(key: string) { syncing.value = key; error.value = ''; notice.value = ''; try { const result = await apiRequest<{ synced: number }>(`/plugins/${key}/sync`, { method: 'POST' }); notice.value = `Synchronized ${result.synced} ${key === 'catalog' ? 'official catalog' : 'market'} entries.`; await Promise.all([refreshConfigs(), key === 'catalog' ? refreshOfficial() : refreshMarket()]) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Plugin synchronization failed.' } finally { syncing.value = '' } }
async function saveConfig(config: SyncConfig) { error.value = ''; notice.value = ''; try { await apiRequest('/plugins/sync-config', { method: 'PUT', body: JSON.stringify({ key: config.key, url: config.url }) }); notice.value = 'Synchronization endpoint saved.'; await refreshConfigs() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not save synchronization endpoint.' } }
async function install(selectedSource = source.value) { if (!selectedSource.trim() || installing.value) return; installing.value = true; error.value = ''; notice.value = ''; try { const result = await apiRequest<{ name?: string }>('/plugins/install', { method: 'POST', body: JSON.stringify({ source: selectedSource.trim() }) }); source.value = ''; notice.value = `Installed ${result.name || 'plugin'}.`; await refreshInstalled(); await refreshOfficial() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not install plugin.' } finally { installing.value = false } }
async function removeApp(app: App) { if (!window.confirm(`Uninstall ${app.name}?`)) return; try { await apiRequest(`/pawapps/${encodeURIComponent(app.id)}`, { method: 'DELETE' }); await refreshInstalled() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not uninstall app.' } }
async function removePlugin(plugin: Plugin) { if (!window.confirm(`Uninstall ${plugin.name}?`)) return; try { await apiRequest(`/plugins/${encodeURIComponent(plugin.id)}`, { method: 'DELETE' }); await Promise.all([refreshInstalled(), refreshOfficial()]) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not uninstall plugin.' } }
function description(plugin: MarketPlugin) { return plugin.locales.en?.description || plugin.locales['en-US']?.description || Object.values(plugin.locales)[0]?.description || 'No description.' }
onMounted(() => { void refreshInstalled(); void refreshConfigs() })
</script>
<template>
  <section class="settings-page apps-page">
    <header class="settings-heading"><div><p class="eyebrow">PLUGIN MANAGEMENT</p><h1>Apps and plugins</h1></div><div class="skills-editor-actions"><button @click="syncOpen = !syncOpen; refreshConfigs()">Sync settings</button><button @click="activeTab === 'installed' ? refreshInstalled() : activeTab === 'official' ? refreshOfficial() : refreshMarket()">Refresh</button></div></header>
    <p v-if="error" class="inline-error" role="alert">{{ error }}</p><p v-if="notice" class="success-notice">{{ notice }}</p>
    <section v-if="syncOpen" class="settings-card sync-settings"><h2>Catalog synchronization</h2><p>Configure and synchronize the Majo official catalog and community market cache.</p><div v-for="config in configs" :key="config.key" class="sync-row"><label><strong>{{ config.key === 'catalog' ? 'Official catalog' : 'Community market' }}</strong><input v-model="config.url" :aria-label="`${config.key} endpoint`" /></label><small>{{ config.status }} · {{ config.synced_count }} entries · {{ config.last_synced_at || 'Never synchronized' }}</small><span><button @click="saveConfig(config)">Save endpoint</button><button :disabled="syncing === config.key" @click="sync(config.key)">{{ syncing === config.key ? 'Synchronizing…' : 'Synchronize' }}</button></span></div></section>
    <nav class="apps-tabs" aria-label="Plugin views"><button :class="{ active: activeTab === 'installed' }" @click="selectTab('installed')">Installed</button><button :class="{ active: activeTab === 'official' }" @click="selectTab('official')">Official catalog</button><button :class="{ active: activeTab === 'market' }" @click="selectTab('market')">Community market</button></nav>
    <section v-if="activeTab === 'installed'" class="apps-tab-content"><div class="settings-card"><h2>Install plugin</h2><form class="skills-editor-actions" @submit.prevent="install()"><input v-model="source" aria-label="Plugin source" placeholder="Local directory, ZIP file, or HTTPS URL"/><button type="submit" :disabled="installing">{{ installing ? 'Installing…' : 'Install plugin' }}</button></form></div><div class="settings-card"><h2>PawApps</h2><p v-if="loading">Loading apps…</p><p v-else-if="!apps.length" class="muted">No PawApps installed.</p><div v-for="app in apps" :key="app.id" class="skills-item"><span><strong>{{ app.name }}</strong><small>{{ app.category || 'App' }} · {{ app.version }} · {{ app.description }}</small></span><button @click="removeApp(app)">Uninstall</button></div></div><div class="settings-card"><h2>Plugins</h2><p v-if="!loading && !plugins.length" class="muted">No plugins installed.</p><div v-for="plugin in plugins" :key="plugin.id" class="skills-item"><span><strong>{{ plugin.name }}</strong><small>{{ plugin.plugin_type || 'Plugin' }} · {{ plugin.version }} · {{ plugin.description }}</small></span><button @click="removePlugin(plugin)">Uninstall</button></div></div></section>
    <section v-else-if="activeTab === 'official'" class="apps-tab-content"><div class="market-toolbar"><p>Official plugins are cached locally after synchronization.</p><button :disabled="syncing === 'catalog'" @click="sync('catalog')">{{ syncing === 'catalog' ? 'Synchronizing…' : 'Synchronize catalog' }}</button></div><p v-if="officialLoading" class="muted">Loading catalog…</p><p v-else-if="!official.length" class="muted">No cached entries. Synchronize the catalog to browse official plugins.</p><article v-for="plugin in official" :key="plugin.id" class="market-card"><div><h2>{{ plugin.name }}</h2><p>{{ plugin.description || 'No description.' }}</p><small>{{ plugin.kind || 'Plugin' }} · {{ plugin.version }}<template v-if="plugin.author"> · {{ plugin.author }}</template><template v-if="plugin.size"> · {{ plugin.size }}</template></small></div><span><small v-if="plugin.installed">Installed {{ plugin.installed_version }}<template v-if="plugin.upgrade_available"> · Update available</template></small><button :disabled="installing || !plugin.install_url" @click="install(plugin.install_url)">{{ plugin.upgrade_available ? 'Update' : plugin.installed ? 'Reinstall' : 'Install' }}</button></span></article></section>
    <section v-else class="apps-tab-content"><form class="market-toolbar" @submit.prevent="refreshMarket"><input v-model="marketSearch" aria-label="Search market" placeholder="Search community plugins"/><select v-model="marketCategory" aria-label="Market category"><option value="">All categories</option><option value="app">Apps</option><option value="agent-tool">Tools</option><option value="provider">Providers</option><option value="command">Commands</option><option value="frontend">Frontend</option><option value="general">General</option></select><button type="submit" :disabled="marketLoading">Search</button><button type="button" :disabled="syncing === 'market'" @click="sync('market')">{{ syncing === 'market' ? 'Synchronizing…' : 'Synchronize market' }}</button></form><p v-if="marketLoading" class="muted">Loading market…</p><p v-else-if="!market.length" class="muted">No cached market entries. Synchronize the market to browse community plugins.</p><article v-for="plugin in market" :key="plugin.id" class="market-card"><div><h2>{{ plugin.display_name }}</h2><p>{{ description(plugin) }}</p><small>{{ plugin.developer || plugin.owner || 'Community' }} · {{ plugin.version }} · {{ plugin.downloads }} downloads</small></div><span><small v-if="plugin.is_featured">Featured</small><a v-if="plugin.details_url" :href="plugin.details_url" target="_blank" rel="noreferrer">Details</a></span></article></section>
  </section>
</template>
